	@ParameterizedTest(name = "{0}")
	@MethodSource("queries")
	void preservesBindingsAcrossCompositionAndReuse(String shape, String text, int copies) {
		try (var connection = repository.getConnection()) {
			var query = connection.prepareTupleQuery(PREFIXES + text);
			for (var entry : Map.of("Alice", ALICE, "Bob", BOB).entrySet()) {
				query.setBinding("label", Values.literal(entry.getKey()));
				try (var result = query.evaluate()) {
					List<IRI> subjects = new ArrayList<>();
					while (result.hasNext()) {
						subjects.add((IRI) result.next().getValue("subject"));
					}
					assertEquals(Collections.nCopies(copies, entry.getValue()), subjects, shape);
				}
			}
			query.setBinding("label", Values.literal("Missing"));
			try (var result = query.evaluate()) {
				assertEquals(List.of(), QueryResults.asList(result), shape);
			}
			query.removeBinding("label");
			try (var result = query.evaluate()) {
				List<BindingSet> rows = QueryResults.asList(result);
				assertEquals(2 * copies, rows.size(), shape);
				assertEquals(Set.of(ALICE, BOB), rows.stream()
						.map(row -> row.getValue("subject"))
						.collect(Collectors.toSet()), shape);
			}
		}
	}

