	@Test
	void lateralDistinguishesIncomingParametersFromRightLocalAssignments() {
		try (var connection = repository.getConnection()) {
			var query = connection.prepareTupleQuery(PREFIXES
					+ "SELECT ?subject WHERE { BIND(\"Bob\" AS ?label) LATERAL { " + PATTERN + " } }");
			query.setBinding("label", Values.literal("Alice"));
			// LATERAL preserves its incoming parameter before considering conflicting values from the left.
			try (var result = query.evaluate()) {
				assertFalse(result.hasNext());
			}
			query.setBinding("label", Values.literal("Bob"));
			try (var result = query.evaluate()) {
				assertEquals(BOB, result.next().getValue("subject"));
				assertFalse(result.hasNext());
			}
			// A sequential assignment inside the right operand owns subsequent reads in that operand.
			query = connection.prepareTupleQuery(PREFIXES
					+ "SELECT ?subject WHERE { VALUES ?n { 1 } LATERAL { BIND(\"Bob\" AS ?label) " + PATTERN + " } }");
			query.setBinding("label", Values.literal("Alice"));
			try (var result = query.evaluate()) {
				assertEquals(BOB, result.next().getValue("subject"));
				assertFalse(result.hasNext());
			}
		}
	}

