	@Test
	void windowArgumentsReceiveParametersAndLocalAssignmentsWin() {
		try (var connection = repository.getConnection()) {
			var query = connection.prepareTupleQuery(PREFIXES
					+ "SELECT (winf:sum(?amount) AS ?total) WHERE { VALUES ?row { 1 2 } }");
			query.setBinding("amount", Values.literal(3));
			try (var result = query.evaluate()) {
				List<BindingSet> rows = QueryResults.asList(result);
				assertEquals(2, rows.size());
				rows.forEach(row -> assertEquals("6", row.getValue("total").stringValue()));
			}
			query = connection.prepareTupleQuery(PREFIXES
					+ "SELECT (winf:sum(?amount) AS ?total) WHERE { VALUES ?amount { 1 2 } }");
			query.setBinding("amount", Values.literal(99));
			try (var result = query.evaluate()) {
				List<BindingSet> rows = QueryResults.asList(result);
				assertEquals(2, rows.size());
				// VALUES owns its output rows, but API substitution still applies to expression reads.
				rows.forEach(row -> assertEquals("198", row.getValue("total").stringValue()));
			}
			query = connection.prepareTupleQuery(PREFIXES
					+ "SELECT (SUM(?amount) AS ?total) WHERE { VALUES ?amount { 1 2 } }");
			query.setBinding("amount", Values.literal(99));
			try (var result = query.evaluate()) {
				assertEquals("198", result.next().getValue("total").stringValue());
			}
			query = connection.prepareTupleQuery(PREFIXES
					+ "SELECT (winf:sum(?amount) AS ?total) WHERE { VALUES ?row { 1 2 } BIND(?row AS ?amount) }");
			query.setBinding("amount", Values.literal(99));
			try (var result = query.evaluate()) {
				List<BindingSet> rows = QueryResults.asList(result);
				assertEquals(2, rows.size());
				rows.forEach(row -> assertEquals("3", row.getValue("total").stringValue()));
			}
		}
	}

